const cfg = $('⚙️ CONFIG').first().json;
const rows = $input.all().map(i => i.json).filter(r => !r.error);
const pending = rows.filter(r => {
  const p = String(r.PROCESADO || '').trim().toUpperCase();
  return p !== 'TRUE' && p !== '1' && p !== 'YES';
});
if (pending.length === 0) return [];
return pending.map(row => ({ json: {
  TEMA:    String(row.TEMA    || '').trim(),
  ESPECIE: String(row.ESPECIE || 'animal').trim(),
  TIPO:    String(row.TIPO    || 'checklist').trim().toLowerCase(),
  PRECIO:  parseFloat(row.PRECIO) || 19.90,
  SHEET_ID: cfg.SHEET_ID, HOJA_PENDIENTES: cfg.HOJA_PENDIENTES,
  GOOGLE_DRIVE_FOLDER_ID: cfg.GOOGLE_DRIVE_FOLDER_ID,
  DEEPSEEK_API_KEY: cfg.DEEPSEEK_API_KEY,
  LEONARDO_API_KEY: cfg.LEONARDO_API_KEY,
  HOTMART_CLIENT_ID: cfg.HOTMART_CLIENT_ID, HOTMART_CLIENT_SECRET: cfg.HOTMART_CLIENT_SECRET,
  MONEDA_HOTMART: cfg.MONEDA_HOTMART, WARRANTY_DIAS: cfg.WARRANTY_DIAS,
  EDUZZ_API_KEY: cfg.EDUZZ_API_KEY, EDUZZ_API_SECRET: cfg.EDUZZ_API_SECRET,
  MONETIZZE_API_KEY: cfg.MONETIZZE_API_KEY
}}));

const p = $input.item.json;
const tipoMap = { checklist:'checklist práctico con ítems accionables', ebook:'ebook completo por capítulos', guia:'guía paso a paso', tutorial:'tutorial detallado con ejercicios' };
const tipoLabel = tipoMap[p.TIPO] || 'infoproducto digital';
const sys = 'Eres experto en infoproductos digitales. RESPONDE SOLO CON JSON VÁLIDO sin markdown.';
const usr = `Crea un ${tipoLabel} sobre "${p.TEMA}" para dueños de ${p.ESPECIE}s.\nJSON ESPERADO:\n{"titulo":"(máx 80 chars)","subtitulo":"subtítulo","descripcion":"(máx 190 chars)","palabras_clave":["k1","k2","k3"],"introduccion":"2-3 párrafos","secciones":[{"titulo":"t","contenido":"texto","items":["item"]}],"conclusion":"texto","cta":"llamada a la acción"}`;
const body = JSON.stringify({ model:'deepseek-chat', temperature:0.72, max_tokens:4000, response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}] });
return { json: { ...p, _dsBody: body } };

const orig = $('📝 Preparar Prompt DeepSeek').item.json;
const resp = $input.item.json;
if (resp.error) return { json: { ...orig, ds:null, _error: resp.error.message||'Error DeepSeek' } };
const raw = resp.choices?.[0]?.message?.content || '';
let ds;
try { ds = JSON.parse(raw); } catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { ds = m ? JSON.parse(m[0]) : null; } catch(e2) { ds = null; }
}
if (!ds?.titulo || !ds?.secciones) return { json: { ...orig, ds:null, _error:'JSON incompleto de DeepSeek' } };
return { json: { ...orig, ds } };

const p = $input.item.json;
if (p._error || !p.ds) return { json: { ...p, htmlContent:'' } };
const {ds,TIPO,ESPECIE} = p;
const PC='#1e40af', AC='#10b981', yr=new Date().getFullYear();
function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function sec(s,i){const isC=Array.isArray(s.items)&&s.items.length>0;const body=isC?`<div class="checklist">${s.items.map(it=>`<div class="ci"><span class="ck">&#9744;</span><span>${esc(it)}</span></div>`).join('')}</div>`:(s.contenido||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')||'<p></p>';return `<div class="section"><h2>${i}. ${esc(s.titulo)}</h2>${body}</div>`;}
const toc=ds.secciones.map((s,i)=>`<li>${i+1}. ${esc(s.titulo)}</li>`).join('');
const secs=ds.secciones.map((s,i)=>sec(s,i+1)).join('');
const intro=(ds.introduccion||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
const concl=(ds.conclusion||'').split(/\n+/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
const css=`*{margin:0;padding:0;box-sizing:border-box}body{font-family:Georgia,serif;color:#1a1a2e;background:#fff;font-size:13pt;line-height:1.8}.cover{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,${PC} 0%,#1e3a8a 100%);color:#fff;padding:80px 60px;text-align:center;page-break-after:always}.cover h1{font-size:2.2em;margin-bottom:24px;max-width:700px}.cover h2{font-size:1.2em;font-weight:300;opacity:.88;margin-bottom:48px}.cover .badge{background:rgba(255,255,255,.15);border:2px solid rgba(255,255,255,.4);border-radius:30px;padding:10px 30px;font-size:.85em;letter-spacing:3px;text-transform:uppercase}.toc{padding:70px 100px;page-break-after:always}.toc h2{font-size:1.7em;color:${PC};border-bottom:3px solid ${PC};padding-bottom:14px;margin-bottom:32px}.toc ol{list-style:none}.toc li{padding:9px 0;border-bottom:1px dotted #d1d5db}.intro,.concl{padding:60px 100px;page-break-after:always}.intro h2,.concl h2{font-size:1.6em;color:${PC};margin-bottom:22px}.intro p,.concl p{margin-bottom:16px}.section{padding:50px 100px;page-break-after:always}.section h2{font-size:1.5em;color:${PC};border-left:5px solid ${AC};padding-left:18px;margin-bottom:28px}.section p{margin-bottom:16px}.checklist{margin-top:8px}.ci{display:flex;align-items:flex-start;gap:14px;padding:12px 16px;margin-bottom:9px;border:1px solid #e5e7eb;border-radius:8px;background:#f9fafb}.ck{font-size:1.2em;color:${PC};flex-shrink:0}.cta-box{margin:40px 100px 60px;padding:50px 60px;background:${PC};color:#fff;border-radius:16px;text-align:center}.cta-box h3{font-size:1.6em;margin-bottom:18px}.cta-box p{font-size:1.1em;opacity:.9}.footer{text-align:center;padding:30px;font-size:.8em;color:#9ca3af;border-top:1px solid #e5e7eb}`;
const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${esc(ds.titulo)}</title><style>${css}</style></head><body><div class="cover"><h1>${esc(ds.titulo)}</h1><h2>${esc(ds.subtitulo)}</h2><div class="badge">${esc(TIPO.toUpperCase())} | ${esc(ESPECIE.toUpperCase())}</div></div><div class="toc"><h2>&#128203; Contenidos</h2><ol>${toc}</ol></div><div class="intro"><h2>Introducción</h2>${intro}</div>${secs}<div class="concl"><h2>Conclusión</h2>${concl}</div><div class="cta-box"><h3>&#128640; ¡Actúa Ahora!</h3><p>${esc(ds.cta)}</p></div><div class="footer">${esc(ds.titulo)} &copy; ${yr}<!-- M6_PROCESSED --></div></body></html>`;
return { json: { ...p, htmlContent:html } };

const data = $input.item.json;
if (data._error || !data.htmlContent) return { json: { ...data, _uploadBody:'', _contentType:'' } };
const B='M6pdf_'+Date.now();
const meta={name:'[M6] '+data.ds.titulo, mimeType:'application/vnd.google-apps.document'};
if (data.GOOGLE_DRIVE_FOLDER_ID) meta.parents=[data.GOOGLE_DRIVE_FOLDER_ID];
const b64=Buffer.from(data.htmlContent,'utf8').toString('base64');
const body=['--'+B,'Content-Type: application/json; charset=UTF-8','',JSON.stringify(meta),'--'+B,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','',b64,'--'+B+'--'].join('\r\n');
return { json: { ...data, _uploadBody:body, _contentType:'multipart/related; boundary="'+B+'"' } };

const orig = $('📦 Preparar Upload a Drive').item.json;
const gdocResp = $('☁️ Crear Google Doc (Drive API)').item.json;
const folderResp = $input.item.json;
const gdocId = (!gdocResp.error && gdocResp.id) ? gdocResp.id : '';
const pdfUrl = gdocId ? `https://docs.google.com/document/d/${gdocId}/export?format=pdf` : '';
const docLink = gdocId ? `https://docs.google.com/document/d/${gdocId}/view` : '';
const driveError = gdocResp.error ? (gdocResp.error.message||'Error Drive API') : (!gdocId ? 'No se obtuvo ID del Doc' : '');
const folderId = (!folderResp.error && folderResp.id) ? folderResp.id : '';
const folderUrl = folderId ? `https://drive.google.com/drive/folders/${folderId}` : '';
return { json: { ...orig, gdocId, pdfUrl, docLink, _driveError:driveError, folderId, folderUrl } };

const p = $input.item.json;
if (p._error || !p.ds) return { json: { ...p, _kitDsBody:'' } };
const sys = 'Eres experto en marketing digital hispanohablante. RESPONDE SOLO CON JSON VÁLIDO.';
const usr = `Kit de marketing completo para "${p.ds.titulo}" (${p.TIPO} para ${p.ESPECIE}s, $${p.PRECIO}).\nJSON ESPERADO:\n{"subject_line":"asunto email (máx 60 chars)","launch_email":"HTML del email (máx 400 palabras)","social_posts":["post1 con emojis","post2","post3","post4","post5"],"affiliate_guide":"markdown guía afiliados (máx 600 palabras)","urgency_phrase":"frase urgencia/escasez"}`;
const body = JSON.stringify({ model:'deepseek-chat', temperature:0.75, max_tokens:3000, response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}] });
return { json: { ...p, _kitDsBody:body } };

const orig = $('📦 Preparar Kit Marketing').item.json;
const resp = $input.item.json;
if (!orig._kitDsBody || orig._error) return { json: { ...orig, kit:{} } };
if (resp.error) return { json: { ...orig, kit:{}, _kitError: resp.error.message||'Error DeepSeek kit' } };
const raw = resp.choices?.[0]?.message?.content || '';
let kit;
try { kit = JSON.parse(raw); } catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { kit = m ? JSON.parse(m[0]) : {}; } catch(e2) { kit = {}; }
}
return { json: { ...orig, kit: kit||{} } };

const p = $input.item.json;
const apiKey = p.LEONARDO_API_KEY || '';
if (!apiKey || apiKey.includes('TU_')) {
  return { json: { ...p, _leonardoImages:{}, _imagesList:'', _errorImagenes:'Leonardo API key no configurada' } };
}
const titulo = p.ds?.titulo || p.TEMA;
const baseUrl = 'https://cloud.leonardo.ai/api/rest/v1';
const hdrs = { 'Authorization':`Bearer ${apiKey}`, 'Content-Type':'application/json', 'Accept':'application/json' };
const fmts = [
  { name:'banner_horizontal', width:1216, height:640 },
  { name:'banner_cuadrado',   width:832,  height:832 },
  { name:'historia_vertical', width:640,  height:1152 },
  { name:'icono_producto',    width:512,  height:512 }
];
const prompt = `Professional digital product cover art for "${titulo}", ${p.TIPO} for ${p.ESPECIE} owners, modern flat design, blue gradient, clean layout, premium quality, no text`;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const jobs = [];
for (const fmt of fmts) {
  try {
    const r = await fetch(`${baseUrl}/generations`, { method:'POST', headers:hdrs, body:JSON.stringify({ prompt, modelId:'b24e16ff-06e3-4a9e-8d1f-7c3e1e9f5c3a', width:fmt.width, height:fmt.height, num_images:1, guidance_scale:7, num_inference_steps:30 }) });
    const d = await r.json();
    jobs.push({ name:fmt.name, genId: d.sdGenerationJob?.generationId || null });
  } catch(e) { jobs.push({ name:fmt.name, genId:null, err:e.message }); }
}
const images = {};
const pending = jobs.filter(j => j.genId);
let elapsed = 0;
while (pending.length > 0 && elapsed < 64000) {
  await sleep(8000); elapsed += 8000;
  for (let i = pending.length-1; i >= 0; i--) {
    try {
      const r = await fetch(`${baseUrl}/generations/${pending[i].genId}`, { headers:hdrs });
      const d = await r.json();
      if (d.generations_by_pk?.status === 'COMPLETE') {
        images[pending[i].name] = d.generations_by_pk.generated_images?.[0]?.url || '';
        pending.splice(i, 1);
      }
    } catch(e) {}
  }
}
for (const j of pending) images[j.name] = '';
for (const j of jobs.filter(x => !x.genId)) images[j.name] = '';
const missing = Object.keys(images).filter(k => !images[k]);
const errMsg = missing.length ? `Sin imagen: ${missing.join(', ')}` : '';
const imagesList = Object.entries(images).map(([k,v]) => `${k}: ${v||'(no generado)'}`).join('\n');
return { json: { ...p, _leonardoImages:images, _imagesList:imagesList, _errorImagenes:errMsg } };

const p = $input.item.json;
const kit = p.kit || {};
const ds  = p.ds  || {};
const images = p._leonardoImages || {};
const emailHtml = kit.launch_email || '(sin email generado)';
const posts = (kit.social_posts||[]).map((t,i) => `<h3>Post ${i+1}</h3><p>${t}</p>`).join('');
const guide = (kit.affiliate_guide||'(sin guía)').replace(/\n/g,'<br>');
const imgRows = Object.entries(images).map(([k,v]) => v ? `<tr><td>${k}</td><td><a href="${v}">${v}</a></td></tr>` : `<tr><td>${k}</td><td>no generado</td></tr>`).join('');
const kitHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Kit Marketing — ${ds.titulo||p.TEMA}</title><style>body{font-family:Arial,sans-serif;max-width:900px;margin:40px auto;color:#222}h1{color:#1e40af}h2{color:#1e40af;border-bottom:2px solid #1e40af;padding-bottom:8px;margin-top:40px}table{border-collapse:collapse;width:100%}td{padding:8px;border:1px solid #ddd}</style></head><body><h1>Kit de Marketing: ${ds.titulo||p.TEMA}</h1><h2>Email de Lanzamiento</h2><p><strong>Asunto:</strong> ${kit.subject_line||''}</p>${emailHtml}<h2>Posts para Redes Sociales</h2>${posts}<h2>Guía para Afiliados</h2><p>${guide}</p><h2>Frase de Urgencia</h2><p>${kit.urgency_phrase||''}</p><h2>Imágenes Generadas</h2><table><tr><th>Formato</th><th>URL</th></tr>${imgRows}</table><h2>PDF del Infoproducto</h2><p><a href="${p.pdfUrl||''}">Descargar PDF</a></p></body></html>`;
const B='M6kit_'+Date.now();
const meta={name:'Kit Marketing — '+(ds.titulo||p.TEMA), mimeType:'application/vnd.google-apps.document'};
if (p.folderId) meta.parents=[p.folderId];
const b64=Buffer.from(kitHtml,'utf8').toString('base64');
const uploadBody=['--'+B,'Content-Type: application/json; charset=UTF-8','',JSON.stringify(meta),'--'+B,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','',b64,'--'+B+'--'].join('\r\n');
return { json: { ...p, _kitUploadBody:uploadBody, _kitContentType:'multipart/related; boundary="'+B+'"' } };

const base = $('📦 Parsear Kit Marketing').item.json;
const leo  = $('🖼️ Leonardo: Imágenes').item.json;
const uploadResp = $('📤 Subir Kit a Drive').item.json;
const kitDocId = (!uploadResp.error && uploadResp.id) ? uploadResp.id : '';
const kitUrl   = kitDocId ? `https://docs.google.com/document/d/${kitDocId}/view` : '';
return { json: {
  ...base,
  _leonardoImages: leo._leonardoImages || {},
  _imagesList:     leo._imagesList     || '',
  _errorImagenes:  leo._errorImagenes  || '',
  kitDocId, kitUrl
}};

const p = $('🔀 Colectar Todos los Datos').item.json;
const eduzzResp    = $('🛒 Eduzz: Crear Producto').item.json;
const monetizzeResp = $('🛒 Monetizze: Crear Producto').item.json;
const eduzzId   = !eduzzResp.error    ? (String(eduzzResp.data?.id || eduzzResp.id || '')) : '';
const eduzzUrl  = !eduzzResp.error    ? (eduzzResp.data?.checkout_url || eduzzResp.checkout_url || '') : '';
const eduzzErr  = eduzzResp.error     ? (eduzzResp.error.message || 'Error Eduzz') : '';
const monId     = !monetizzeResp.error ? (String(monetizzeResp.data?.id || monetizzeResp.id || '')) : '';
const monUrl    = !monetizzeResp.error ? (monetizzeResp.data?.checkout_url || monetizzeResp.checkout_url || '') : '';
const monErr    = monetizzeResp.error  ? (monetizzeResp.error.message || 'Error Monetizze') : '';
const hotmartBody = (p.ds && p.pdfUrl) ? JSON.stringify({ name: p.ds.titulo, description: p.ds.descripcion||p.ds.titulo, format:'EBOOK', warranty: p.WARRANTY_DIAS||30, price:{ value:p.PRECIO, currency_code:p.MONEDA_HOTMART||'BRL' }, resource_url:p.pdfUrl }) : '{}';
return { json: { ...p, _hotmartBody:hotmartBody, eduzzId, eduzzUrl, _eduzzError:eduzzErr, monetizzeId:monId, monetizzeUrl:monUrl, _monetizzeError:monErr } };

const params = $('🗂️ Preparar Payload Hotmart').item.json;
const tokenResp = $input.item.json;
const token = (!tokenResp.error && tokenResp.access_token) ? tokenResp.access_token : '';
const tokenError = tokenResp.error ? (tokenResp.error.message||'Error token Hotmart') : (token ? '' : 'Token vacío');
return { json: { ...params, _hotmartToken:token, _tokenError:tokenError } };

const p = $('🔀 Merge Token con Params').item.json;
const hotmartResp = $input.item.json;
const driveOK   = !!p.gdocId && !p._driveError;
const tokenOK   = !!p._hotmartToken && !p._tokenError;
const hotmartOK = !hotmartResp.error && !!(hotmartResp.id || hotmartResp.product?.id);
let errorMsg = '';
if (p._error)      errorMsg = p._error;
else if (!driveOK) errorMsg = p._driveError || 'Error creando Google Doc';
else if (!tokenOK) errorMsg = p._tokenError || 'Error token Hotmart';
else if (!hotmartOK) errorMsg = hotmartResp.error?.message || JSON.stringify(hotmartResp).substring(0,120);
const success = driveOK && tokenOK && hotmartOK && !p._error;
return { json: {
  _tema:            p.TEMA,
  _titulo:          p.ds?.titulo || p.TEMA,
  _success:         success,
  PROCESADO:        success ? 'TRUE' : 'FALSE',
  PDF_URL:          p.pdfUrl          || '',
  HOTMART_ID:       success ? String(hotmartResp.id || hotmartResp.product?.id || '') : '',
  HOTMART_LINK:     success ? (hotmartResp.links?.checkout_url || hotmartResp.checkout_url || 'ver panel Hotmart') : '',
  CARPETA_DRIVE_URL: p.folderUrl       || '',
  KIT_MARKETING_URL: p.kitUrl          || '',
  URL_EDUZZ:         p.eduzzUrl        || '',
  URL_MONETIZZE:     p.monetizzeUrl    || '',
  IMAGENES_LISTA:    p._imagesList     || '',
  ERROR:             errorMsg,
  ERROR_IMAGENES:    p._errorImagenes  || '',
  SHEET_ID:          p.SHEET_ID,
  HOJA_PENDIENTES:   p.HOJA_PENDIENTES
}};
